// Espera 1 item com a chave "data" sendo um array de empresas
// [
//   {
//     "data": [ {company_id, company, ...}, {...} ]
//   }
// ]

// 1) Array com todos os objetos de empresa (mantendo todos os campos)
const companies = $json.data || [];

// 2) Form JSON para o dropdown, usando o nome da empresa como opção
const formJson = [
  {
    fieldLabel: "Escolha a empresa deste lead",
    fieldType: "dropdown",
    requiredField: true,
    fieldOptions: {
      values: companies.map(c => ({
        option: c.company, // label exibido no dropdown
      })),
    },
  },
];

// 3) Retorna um único objeto com tudo
return [
  {
    json: {
      formJson,
      formJsonString: JSON.stringify(formJson, null, 2),
      companies,
    },
  },
];

